class Scope {
    Part part_;
    QueryPhase previous_phase_=query_phase;
    Part previous_host_query_part_=host_query_part;
    ManagementQueryParts previous_management_parts_=management_query_parts;
    std::chrono::steady_clock::time_point started_=std::chrono::steady_clock::now();
public:
    explicit Scope(Part part):part_(part){management_query_parts=management_parts_for(part_,previous_management_parts_);query_phase=phase_for(part_,previous_phase_);if(part_==Part::Take)++take_depth;if(part_==Part::QuestStores)++quest_store_depth;if(part_==Part::ClientPartyPrepare)++client_party_prepare_depth;
        if(part_==Part::HostCapture){++host_capture_depth;host_query_part=Part::HostQueryOther;}
        switch(part_){
        case Part::HostCaptureManagement:host_query_part=Part::HostQueryManagement;break;
        case Part::HostCaptureManagementFinish:host_query_part=Part::HostQueryManagementFinish;break;
        case Part::HostCaptureEconomy:host_query_part=Part::HostQueryEconomy;break;
        case Part::HostCaptureParty:host_query_part=Part::HostQueryParty;break;
        case Part::HostCaptureRelease:host_query_part=Part::HostQueryRelease;break;
        default:break;
        }
    }
    Scope(const Scope&)=delete;
    Scope& operator=(const Scope&)=delete;
    ~Scope(){const auto ns=uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-started_).count());if(part_==Part::Take)--take_depth;if(part_==Part::QuestStores)--quest_store_depth;if(part_==Part::ClientPartyPrepare)--client_party_prepare_depth;record(part_,ns);query_phase=previous_phase_;if(part_==Part::HostCapture)--host_capture_depth;host_query_part=previous_host_query_part_;management_query_parts=previous_management_parts_;}
};
